#!/usr/bin/env python3
"""Modernized climate data analysis script.

Replaces the legacy Python 2.7 implementation with a Python 3 compatible
version that uses current pandas, pathlib, and configparser APIs.
"""

import configparser
from pathlib import Path

import pandas as pd

BASE_DIR = Path(__file__).resolve().parent
DATA_FILE = BASE_DIR / "climate_analyzer" / "sample_data" / "climate_data.csv"
CONFIG_FILE = BASE_DIR / "climate_analyzer" / "config.ini"


def load_config(config_path: Path) -> configparser.ConfigParser:
    """Load the INI configuration file using UTF-8 encoding."""
    config = configparser.ConfigParser()
    if config_path.is_file():
        config.read(config_path, encoding="utf-8")
    return config


def load_temperature_data(filename: Path) -> pd.DataFrame:
    """Load climate data from a UTF-8 encoded CSV file."""
    return pd.read_csv(filename, encoding="utf-8", parse_dates=["date"])


def calculate_anomalies(temperature_series: pd.Series) -> pd.Series:
    """Calculate temperature anomalies relative to the series mean."""
    return temperature_series - temperature_series.mean()


def main() -> None:
    config = load_config(CONFIG_FILE)

    data = load_temperature_data(DATA_FILE)

    for station_id, group in data.groupby("station_id"):
        mean_temperature = group["temperature"].mean()
        print(f"Station {station_id} mean temperature: {mean_temperature:.1f}°C")

    if config.has_section("analysis"):
        baseline_years = config.get("analysis", "baseline_years", fallback="")
        if baseline_years:
            print(f"Configured baseline years: {baseline_years}")


if __name__ == "__main__":
    main()

